-- CORTIS V1 Phase 6: complete reviewed HU/DE/EN interface phrase catalog.
-- Generated from catalog.psv; edit its source and regenerate rather than editing applied migrations.
-- Uses V11/V12 schema; never changes V11-V13 applied files.
-- All keys have a nonnull category. Existing translations are preserved.

CREATE TEMP TABLE cortis_i18n_seed (
    category_name TEXT NOT NULL,
    keyword TEXT NOT NULL,
    hu TEXT NOT NULL,
    de TEXT NOT NULL,
    en TEXT NOT NULL
) ON COMMIT DROP;


DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM cortis_i18n_seed GROUP BY category_name, keyword HAVING count(*)>1) THEN
    RAISE EXCEPTION 'Duplicate category.keyword in CORTIS translation seed';
  END IF;
  IF (SELECT count(*) FROM translation.language WHERE code IN ('hu','de','en') AND deleted_at IS NULL)<>3 THEN
    RAISE EXCEPTION 'Required hu/de/en languages do not exist as active rows';
  END IF;
END $$;

SELECT DISTINCT category_name FROM cortis_i18n_seed
ON CONFLICT (category_name) DO NOTHING;
UPDATE translation.category c SET deleted_at=NULL, updated_at=now()
WHERE c.deleted_at IS NOT NULL AND EXISTS(SELECT 1 FROM cortis_i18n_seed s WHERE s.category_name=c.category_name);

SELECT DISTINCT keyword FROM cortis_i18n_seed
ON CONFLICT (keyword) DO NOTHING;
UPDATE translation.keyword k SET deleted_at=NULL, updated_at=now()
WHERE k.deleted_at IS NOT NULL AND EXISTS(SELECT 1 FROM cortis_i18n_seed s WHERE s.keyword=k.keyword);

-- Respect existing translations. Restore soft-deleted keys if applicable.
SELECT k.id,l.id,c.id, v.translation_text
FROM cortis_i18n_seed s
JOIN translation.category c ON c.category_name=s.category_name
JOIN translation.keyword k ON k.keyword=s.keyword
CROSS JOIN LATERAL (VALUES ('hu',s.hu),('de',s.de),('en',s.en)) AS v(language_code,translation_text)
JOIN translation.language l ON l.code=v.language_code
ON CONFLICT (keyword_id,language_id,category_id) DO UPDATE SET
  deleted_at=NULL, updated_at=now(),
  translation_text=CASE WHEN trim(target.translation_text)='' THEN EXCLUDED.translation_text
                        ELSE target.translation_text END
WHERE target.deleted_at IS NOT NULL OR trim(target.translation_text)='';

-- Flyway must abort if any seeded locale is absent or empty.
DO $$
DECLARE missing_count INTEGER;
BEGIN
  SELECT count(*) INTO missing_count FROM cortis_i18n_seed s
  CROSS JOIN (VALUES ('hu'),('de'),('en')) AS wanted(code)
  JOIN translation.category c ON c.category_name=s.category_name AND c.deleted_at IS NULL
  JOIN translation.keyword k ON k.keyword=s.keyword AND k.deleted_at IS NULL
  JOIN translation.language l ON l.code=wanted.code AND l.deleted_at IS NULL
  LEFT JOIN translation.text t ON t.keyword_id=k.id AND t.category_id=c.id
     AND t.language_id=l.id AND t.deleted_at IS NULL AND trim(t.translation_text)<>''
  WHERE t.id IS NULL;
  IF missing_count<>0 THEN
    RAISE EXCEPTION 'Translation seed incomplete; % missing or empty HU/DE/EN cells', missing_count;
  END IF;
END $$;
